```cpp
#include <iostream>
#include <string>
#include <regex>

std::string convertMarkdownToHtml(std::string& markdown) {
    // Reemplazar la sintaxis de Markdown por su equivalente HTML
    std::string html;

    // Encabezados
    std::regex header_regex("^#{1,6}(.*)$");
    std::smatch header_match;
    if (std::regex_match(markdown, header_match, header_regex)) {
        std::string level = std::to_string(header_match.prefix().length()) + " ";
        std::string content = header_match.str(1);
        html += "<h" + level + ">" + content + "</h" + level + ">\n";
        markdown.erase(0, header_match.position().length()); // Eliminar el encabezado del texto original
    }

    // Enlaces
    std::regex link_regex("\\[([^\\]]*)\\]\\(([^\\)]*)\\)");
    std::smatch link_match;
    while (std::regex_search(markdown, link_match, link_regex)) {
        std::string text = link_match.str(1);
        std::string href = link_match.str(2);
        html += "<a href=\"" + href + "\">" + text + "</a>\n";
        markdown.erase(link_match.position(), link_match.length()); // Eliminar el enlace del texto original
    }

    // Citas
    std::regex blockquote_regex("^> *([^>]*?)$");
    std::smatch blockquote_match;
    while (std::regex_search(markdown, blockquote_match, blockquote_regex)) {
        std::string content = blockquote_match.str(1);
        html += "<blockquote>\n" + content + "</blockquote>\n";
        markdown.erase(0, blockquote_match.position().length()); // Eliminar la cita del texto original
    }

    // Código
    std::regex code_regex("^`{3}(. *)`{3}$");
    std::smatch code_match;
    if (std::regex_match(markdown, code_match, code_regex)) {
        std::string content = code_match.str(1);
        html += "<pre><code>" + content + "</code></pre>\n";
        markdown.erase(0, code_match.position().length()); // Eliminar el código del texto original
    }

    // Lista desordenada
    std::regex unordered_list_regex("^ *([-+*])[ ]+(. *)$");
    std::smatch unordered_list_match;
    while (std::regex_search(markdown, unordered_list_match, unordered_list_regex)) {
        std::string marker = unordered_list_match.str(1);
        std::string content = unordered_list_match.str(2);
        html += "<ul>\n";
        std::string items[] = { content };
        std::regex item_regex("^[ ]{2,3}([-+*])[ ]+(. *)$");
        std::smatch item_match;
        while (std::regex_search(content, item_match, item_regex)) {
            std::string item_marker = item_match.str(1);
            std::string item_content = item_match.str(2);
            content.erase(item_match.position(), item_match.length()); // Eliminar el item del contenido original
            html += "  <li>" + item_marker + " " + item_content + "</li>\n";
        }
        html += "</ul>\n";
        markdown.erase(0, unordered_list_match.position().length()); // Eliminar la lista del texto original
    }

    // Lista ordenada
    std::regex ordered_list_regex("^ *([0-9]+[.]|\\d+[)])[ ]+(. *)$");
    std::smatch ordered_list_match;
    while (std::regex_search(markdown, ordered_list_match, ordered_list_regex)) {
        std::string marker = ordered_list_match.str(1);
        std::string content = ordered_list_match.str(2);
        html += "<ol>\n";
        std::string items[] = { content };
        std::regex item_regex("^[ ]{2,3}([0-9]+[.]|\\d+[])[ ]+(. *)$");
        std::smatch item_match;
        while (std::regex_search(content, item_match, item_regex)) {
            std::string item_marker = item_match.str(1);
            std::string item_content = item_match.str(2);
            content.erase(item_match.position(), item_match.length()); // Eliminar el item del contenido original
            html += "  <li>" + item_marker + " " + item_content + "</li>\n";
        }
        html += "</ol>\n";
        markdown.erase(0, ordered_list_match.position().length()); // Eliminar la lista del texto original
    }

    // Texto en negrita
    std::regex bold_regex("\\*([^\\*]*)\\*");
    std::smatch bold_match;
    while (std::regex_search(markdown, bold_match, bold_regex)) {
        std::string content = bold_match.str(1);
        html += "<strong>" + content + "</strong>\n";
        markdown.erase(bold_match.position(), bold_match.length()); // Eliminar el texto en negrita del texto original
    }

    // Texto en cursiva
    std::regex italic_regex("_(. *)_");
    std::smatch italic_match;
    while (std::regex_search(markdown, italic_match, italic_regex)) {
        std::string content = italic_match.str(1);
        html += "<em>" + content + "</em>\n";
        markdown.erase(italic_match.position(), italic_match.length()); // Eliminar el texto en cursiva del texto original
    }

    // Texto en negrita y cursiva
    std::regex bold_italic_regex("\\*([^\\*]*)\\*_(. *)_");
    std::smatch bold_italic_match;
    while (std::regex_search(markdown, bold_italic_match, bold_italic_regex)) {
        std::string content_bold = bold_italic_match.str(1);
        std::string content_italic = bold_italic_match.str(2);
        html += "<strong>" + content_bold + "</strong><em>" + content_italic + "</em>\n";
        markdown.erase(bold_italic_match.position(), bold_italic_match.length()); // Eliminar el texto en negrita y cursiva del texto original
    }

    // Texto en línea
    std::regex inline_code_regex("`([^`]*)`");
    std::smatch inline_code_match;
    while (std::regex_search(markdown, inline_code_match, inline_code_regex)) {
        std::string content = inline_code_match.str(1);
        html += "<code>" + content + "</code>\n";
        markdown.erase(inline_code_match.position(), inline_code_match.length()); // Eliminar el texto en línea del texto original
    }

    // Texto en bloque
    std::regex paragraph_regex("([^\\n]*)");
    std::smatch paragraph_match;
    while (std::regex_search(markdown, paragraph_match, paragraph_regex)) {
        std::string content = paragraph_match.str(1);
        html += "<p>" + content + "</p>\n";
        markdown.erase(paragraph_match.position(), paragraph_match.length()); // Eliminar el párrafo del texto original
    }

    // Resto de texto (sin formato)
    html += markdown;

    return html;
}

int main() {
